+import type { QueryInstance } from '../types';
+
+function complete(world: World, query: QueryInstance, entity: Entity, traits: readonly any[], masks?: number[][]) {
+    const eid = getEntityId(entity);
+    for (const trait of traits) {
+        const instance = query.traitInstances.all.find((item) => item.trait === trait)!;
+        const mask = (masks ?? world[$internal].entityMasks)[instance.generationId]?.[eid] || 0;
+        if ((mask & instance.bitflag) !== instance.bitflag) return false;
+    }
+    return true;
+}
+
+export function matchesAspectTracking(world: World, query: QueryInstance, entity: Entity): boolean {
+    const ctx = world[$internal];
+    const eid = getEntityId(entity);
+    for (const tracking of query.aspectTracking) {
+        const now = complete(world, query, entity, tracking.aspect.traits);
+        const before = complete(
+            world,
+            query,
+            entity,
+            tracking.aspect.traits,
+            ctx.trackingSnapshots.get(tracking.id)
+        );
+        if (tracking.type === 'add' && (before || !now)) return false;
+        if (tracking.type === 'remove' && (!before || now)) return false;
+        if (tracking.type === 'change') {
+            if (!now) return false;
+            const changed = ctx.changedMasks.get(tracking.id)!;
+            let anyChanged = false;
+            for (const trait of tracking.aspect.traits) {
+                const instance = query.traitInstances.all.find((item) => item.trait === trait)!;
+                if (((changed[instance.generationId]?.[eid] || 0) & instance.bitflag) !== 0) {
+                    anyChanged = true;
+                    break;
+                }
+            }
+            if (!anyChanged) return false;
+        }
+    }
+    return true;
+}
