import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation } from '../relation/utils/is-relation';
import type { Schema } from '../storage';
import type { Trait, TraitRecord, TraitValue } from '../trait/types';

let aspectId = 0;

export type AspectInput = Trait | Aspect;

export type Aspect<TTraits extends readonly Trait[] = readonly Trait[]> = {
    readonly id: number;
    readonly traits: TTraits;
    readonly schema: AspectSchema<TTraits>;
    readonly [$internal]: { aspect: true };
} & ((params?: Partial<AspectRecord<TTraits>>) => [Aspect<TTraits>, Partial<AspectRecord<TTraits>>]);

type AspectSchema<T extends readonly Trait[]> = T extends readonly [infer First, ...infer Rest]
    ? First extends Trait<infer S>
        ? S & (Rest extends readonly Trait[] ? AspectSchema<Rest> : {})
        : {}
    : {};

export type AspectRecord<T extends readonly Trait[] = readonly Trait[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Trait
        ? TraitRecord<First> & (Rest extends readonly Trait[] ? AspectRecord<Rest> : {})
        : {}
    : {};

export type AspectValue<T extends Aspect = Aspect> = Partial<AspectRecord<T['traits']>>;

export function isAspect(value: unknown): value is Aspect {
    return (value as Aspect | null | undefined)?.[$internal]?.aspect === true;
}

export function createAspect<T extends readonly [AspectInput, AspectInput, ...AspectInput[]]>(
    ...inputs: T
): Aspect<FlattenAspectInputs<T>> {
    const traits: Trait[] = [];
    for (const input of inputs) {
        if (isRelation(input)) throw new Error('Koota: Relations cannot be aspect constituents.');
        const inputTraits = isAspect(input) ? input.traits : [input];
        for (const trait of inputTraits) {
            if (trait[$internal].relation)
                throw new Error('Koota: Relation traits cannot be aspect constituents.');
            traits.push(trait);
        }
    }

    const schema: Record<string, unknown> = {};
    for (const trait of traits) {
        const traitSchema = trait.schema as Schema;
        if (typeof traitSchema === 'function')
            throw new Error('Koota: AoS traits cannot be aspect constituents.');
        for (const key of Object.keys(traitSchema)) {
            if (key in schema) throw new Error(`Koota: Aspect field '${key}' is defined more than once.`);
            schema[key] = traitSchema[key];
        }
    }

    const id = aspectId++;
    const aspect = Object.assign(
        (params: Partial<AspectRecord> = {}) => [aspect, params] as [typeof aspect, typeof params],
        { [$internal]: { aspect: true } }
    ) as Aspect<FlattenAspectInputs<T>>;

    Object.defineProperties(aspect, {
        id: { value: id, enumerable: true },
        traits: { value: Object.freeze(traits), enumerable: true },
        schema: { value: Object.freeze(schema), enumerable: true },
    });

    return aspect;
}

export function getAspectTraitValue(trait: Trait, value: Record<string, unknown> | undefined) {
    if (!value || trait[$internal].type === 'tag') return undefined;
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(trait.schema)) {
        if (key in value) result[key] = value[key];
    }
    return result;
}

export function mergeAspectValues(values: (Record<string, unknown> | undefined)[]) {
    return Object.assign({}, ...values) as Record<string, unknown>;
}

export function aspectHasTraits(has: (trait: Trait) => boolean, aspect: Aspect): boolean {
    return aspect.traits.every(has);
}

type FlattenAspectInput<T> = T extends Aspect<infer Traits> ? Traits : T extends Trait ? [T] : [];
export type FlattenAspectInputs<T extends readonly AspectInput[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? [...FlattenAspectInput<First>, ...(Rest extends readonly AspectInput[] ? FlattenAspectInputs<Rest> : [])]
    : [];

